interface FamilyMember {
  id: string;
  name: string;
  relationship: string;
  avatar?: string;
  lastSeen: Date;
  permissions: string[];
  notificationPreferences: {
    emergencyAlerts: boolean;
    weeklyReports: boolean;
    milestones: boolean;
  };
}

interface ProgressShare {
  id: string;
  type: 'milestone' | 'improvement' | 'concern' | 'achievement';
  title: string;
  description: string;
  value?: number;
  previousValue?: number;
  unit?: string;
  date: Date;
  celebrateWith: string[];
  reactions: { memberId: string; reaction: string }[];
}

interface FamilyDashboardProps {
  healthData: ProcessedHealthData;
}

export default function FamilyDashboard({
  healthData,
}: Readonly<FamilyDashboardProps>) {
  const [familyMembers, setFamilyMembers] = useKV<FamilyMember[]>(
    'family-members',
    [
      {
        id: '1',
        name: 'Sarah Johnson',
        relationship: 'Daughter',
        lastSeen: new Date(Date.now() - 1000 * 60 * 30), // 30 minutes ago
        permissions: ['view-health', 'receive-alerts'],
        notificationPreferences: {
          emergencyAlerts: true,
          weeklyReports: true,
          milestones: true,
        },
      },
      {
        id: '2',
        name: 'Michael Johnson',
        relationship: 'Son',
        lastSeen: new Date(Date.now() - 1000 * 60 * 60 * 2), // 2 hours ago
        permissions: ['view-health', 'receive-alerts'],
        notificationPreferences: {
          emergencyAlerts: true,
          weeklyReports: false,
          milestones: true,
        },
      },
    ]
  );

  const [progressShares, setProgressShares] = useKV<ProgressShare[]>(
    'progress-shares',
    [
      {
        id: '1',
        type: 'achievement',
        title: 'Daily Step Goal Achieved!',
        description: 'Completed 10,000 steps for 7 consecutive days',
        value: 10247,
        unit: 'steps',
        date: new Date(Date.now() - 1000 * 60 * 60 * 24), // 1 day ago
        celebrateWith: ['1', '2'],
        reactions: [
          { memberId: '1', reaction: '🎉' },
          { memberId: '2', reaction: '👏' },
        ],
      },
      {
        id: '2',
        type: 'improvement',
        title: 'Fall Risk Score Improved',
        description:
          'Your balance and stability metrics have improved this week',
        value: 72,
        previousValue: 65,
        unit: 'score',
        date: new Date(Date.now() - 1000 * 60 * 60 * 48), // 2 days ago
        celebrateWith: ['1'],
        reactions: [{ memberId: '1', reaction: '❤️' }],
      },
    ]
  );

  const addReaction = (shareId: string, memberId: string, reaction: string) => {
    setProgressShares(
      (current) =>
        current?.map((share) =>
          share.id === shareId
            ? {
                ...share,
                reactions: [
                  ...share.reactions.filter((r) => r.memberId !== memberId),
                  { memberId, reaction },
                ],
              }
            : share
        ) || []
    );
  };

  const shareProgress = async () => {
    // Generate a new progress share based on current health data
    const newShare: ProgressShare = {
      id: Date.now().toString(),
      type: 'milestone',
      title: 'Weekly Health Summary',
      description: `Health score: ${healthData.healthScore || 0}/100. Keep up the great work!`,
      value: healthData.healthScore || 0,
      unit: 'health score',
      date: new Date(),
      celebrateWith: (familyMembers ?? []).map((m) => m.id),
      reactions: [],
    };

    setProgressShares((current) => [newShare, ...(current || [])]);
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'achievement':
        return CheckCircle;
      case 'improvement':
        return TrendingUp;
      case 'milestone':
        return Star;
      case 'concern':
        return AlertTriangle;
      default:
        return Activity;
    }
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'achievement':
        return 'text-green-600';
      case 'improvement':
        return 'text-blue-600';
      case 'milestone':
        return 'text-purple-600';
      case 'concern':
        return 'text-orange-600';
      default:
        return 'text-gray-600';
    }
  };

  const getHealthStatusMessage = (score: number) => {
    if (score >= 80) {
      return 'Excellent health status! Keep it up!';
    } else if (score >= 60) {
      return 'Good health with room for improvement';
    } else {
      return 'Health needs attention - consider consulting with healthcare providers';
    }
  };

  const getRelativeTime = (date: Date) => {
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const minutes = Math.floor(diff / (1000 * 60));
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days}d ago`;
    if (hours > 0) return `${hours}h ago`;
    if (minutes > 0) return `${minutes}m ago`;
    return 'Just now';
  };

  // Calculate family engagement metrics
  const activeFamilyMembers = (familyMembers ?? []).filter(
    (member) =>
      new Date().getTime() - member.lastSeen.getTime() < 1000 * 60 * 60 * 24 // Active in last 24h
  ).length;

  const totalReactions = (progressShares || []).reduce(
    (sum, share) => sum + share.reactions.length,
    0
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
        <div>
          <h2 className="text-2xl font-bold text-foreground">
            Family Dashboard
          </h2>
          <p className="text-muted-foreground">
            Share your health journey with loved ones
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button onClick={shareProgress} className="flex items-center gap-2">
            <Heart className="h-4 w-4" />
            Share Update
          </Button>
        </div>
      </div>

      {/* Family Overview */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-primary text-2xl font-bold">
              {(familyMembers || []).length}
            </div>
            <div className="text-muted-foreground text-sm">Family Members</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-green-600">
              {activeFamilyMembers}
            </div>
            <div className="text-muted-foreground text-sm">Active Today</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-purple-600">
              {totalReactions}
            </div>
            <div className="text-muted-foreground text-sm">Total Support</div>
          </CardContent>
        </Card>
      </div>

      {/* Current Health Status - Simplified for Family */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Activity className="h-5 w-5" />
            Current Health Status
          </CardTitle>
          <CardDescription>
            A simple overview of your health for your family
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium">Overall Health</span>
                <span>
                  <p className="text-muted-foreground text-xs">
                    {getHealthStatusMessage(healthData.healthScore || 0)}
                  </p>
                </span>
              </div>
              <Progress value={healthData.healthScore || 0} className="h-2" />
              <p className="text-muted-foreground text-xs">
                {(healthData.healthScore || 0) >= 80
                  ? 'Excellent health status! Keep it up!'
                  : (healthData.healthScore || 0) >= 60
                    ? 'Good health with room for improvement'
                    : 'Health needs attention - consider consulting with healthcare providers'}
              </p>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium">Fall Risk</span>
                {(() => {
                  const hasHighRisk =
                    healthData.fallRiskFactors?.some(
                      (f) => f.risk === 'high'
                    ) ?? false;
                  const hasModerateRisk =
                    healthData.fallRiskFactors?.some(
                      (f) => f.risk === 'moderate'
                    ) ?? false;

                  const badgeVariant = hasHighRisk
                    ? 'destructive'
                    : hasModerateRisk
                      ? 'default'
                      : 'secondary';
                  const badgeText = hasHighRisk
                    ? 'HIGH'
                    : hasModerateRisk
                      ? 'MEDIUM'
                      : 'LOW';

                  return <Badge variant={badgeVariant}>{badgeText}</Badge>;
                })()}
              </div>
              <p className="text-muted-foreground text-xs">
                {healthData.fallRiskFactors?.some((f) => f.risk === 'high')
                  ? 'Higher fall risk detected - extra care recommended'
                  : 'Fall risk is well managed'}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Family Members */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            Your Care Circle
          </CardTitle>
          <CardDescription>
            Family members following your health journey
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-2">
            {(familyMembers ?? []).map((member) => (
              <div
                key={member.id}
                className="flex items-center justify-between rounded-lg border p-3"
              >
                <div className="flex items-center gap-3">
                  <Avatar>
                    <AvatarImage src={member.avatar} />
                    <AvatarFallback>
                      {member.name
                        .split(' ')
                        .map((n) => n[0])
                        .join('')}
                    </AvatarFallback>
                  </Avatar>
                  <div>
                    <h4 className="font-medium">{member.name}</h4>
                    <p className="text-muted-foreground text-sm">
                      {member.relationship}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <div className="mb-1 flex items-center gap-2">
                    <div
                      className={`h-2 w-2 rounded-full ${
                        new Date().getTime() - member.lastSeen.getTime() <
                        1000 * 60 * 60
                          ? 'bg-green-500'
                          : 'bg-gray-400'
                      }`}
                    />
                    <span className="text-muted-foreground text-xs">
                      {getRelativeTime(member.lastSeen)}
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                      <MessageCircle className="h-3 w-3" />
                    </Button>
                    <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                      <Phone className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Progress & Achievements */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Star className="h-5 w-5" />
            Recent Progress & Achievements
          </CardTitle>
          <CardDescription>
            Share your health milestones with your family
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {progressShares?.map((share) => {
              const IconComponent = getTypeIcon(share.type);
              return (
                <div key={share.id} className="rounded-lg border p-4">
                  <div className="mb-3 flex items-start justify-between">
                    <div className="flex items-center gap-3">
                      <div
                        className={`rounded-full bg-gray-100 p-2 ${getTypeColor(share.type)}`}
                      >
                        <IconComponent className="h-5 w-5" />
                      </div>
                      <div>
                        <h4 className="font-medium">{share.title}</h4>
                        <p className="text-muted-foreground text-sm">
                          {share.description}
                        </p>
                      </div>
                    </div>
                    <span className="text-muted-foreground text-xs">
                      {getRelativeTime(share.date)}
                    </span>
                  </div>

                  {share.value && (
                    <div className="mb-3">
                      <div className="flex items-center gap-2">
                        <span className="text-primary text-2xl font-bold">
                          {share.value}
                        </span>
                        <span className="text-muted-foreground text-sm">
                          {share.unit}
                        </span>
                        {share.previousValue && (
                          <Badge variant="secondary" className="text-green-600">
                            +{share.value - share.previousValue}
                          </Badge>
                        )}
                      </div>
                    </div>
                  )}

                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      {share.reactions.map((reaction) => (
                        <span key={reaction.memberId} className="text-lg">
                          {reaction.reaction}
                        </span>
                      ))}
                      {share.reactions.length === 0 && (
                        <span className="text-muted-foreground text-sm">
                          No reactions yet
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-1">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => addReaction(share.id, '1', '❤️')}
                        className="h-8 px-2"
                      >
                        ❤️
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => addReaction(share.id, '1', '🎉')}
                        className="h-8 px-2"
                      >
                        🎉
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => addReaction(share.id, '1', '👏')}
                        className="h-8 px-2"
                      >
                        👏
                      </Button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Emergency & Safety */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Shield className="h-5 w-5" />
            Emergency & Safety
          </CardTitle>
          <CardDescription>
            Quick access to emergency features for peace of mind
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-2">
            <Button variant="outline" className="flex h-16 flex-col gap-2">
              <Phone className="h-6 w-6 text-red-600" />
              <span className="text-sm">Emergency Call</span>
            </Button>
            <Button variant="outline" className="flex h-16 flex-col gap-2">
              <MessageCircle className="h-6 w-6 text-blue-600" />
              <span className="text-sm">Send Check-in</span>
            </Button>
            <Button variant="outline" className="flex h-16 flex-col gap-2">
              <MapPin className="h-6 w-6 text-green-600" />
              <span className="text-sm">Share Location</span>
            </Button>
            <Button variant="outline" className="flex h-16 flex-col gap-2">
              <Bell className="h-6 w-6 text-purple-600" />
              <span className="text-sm">Test Alert System</span>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Advanced Gait Dashboard Component
 * Comprehensive gait analysis combining LiDAR and movement pattern analysis
 */

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Activity,
  Brain,
  CheckCircle,
  Clock,
  Eye,
  Heart,
  Play,
  Target,
  Timer,
} from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';
import { LiDARGaitAnalyzer } from './LiDARGaitAnalyzer';
import { WalkingPatternVisualizer } from './WalkingPatternVisualizer';

interface GaitAnalysisSession {
  id: string;
  type: 'lidar' | 'pattern' | 'combined';
  startTime: Date;
  endTime?: Date;
  status: 'idle' | 'recording' | 'analyzing' | 'completed' | 'error';
  data?: Record<string, unknown>;
  insights: string[];
  recommendations: readonly string[];
  riskScore: number;
}

type DashboardView = 'analysis' | 'history' | 'insights' | 'settings';
type AnalysisMode = 'lidar' | 'pattern' | 'combined';

interface GaitDashboardProps {
  readonly enableLiDAR?: boolean;
  readonly enablePatternAnalysis?: boolean;
  readonly autoSave?: boolean;
}

export function GaitDashboard({
  enableLiDAR = true,
  enablePatternAnalysis = true,
  autoSave = true,
}: GaitDashboardProps) {
  const [activeSession, setActiveSession] =
    useState<GaitAnalysisSession | null>(null);
  const [sessionHistory, setSessionHistory] = useState<GaitAnalysisSession[]>(
    []
  );
  const [analysisMode, setAnalysisMode] = useState<AnalysisMode>('combined');
  const [isRecording, setIsRecording] = useState(false);
  const [dashboardView, setDashboardView] = useState<DashboardView>('analysis');

  const showToast = (
    message: string,
    type: 'success' | 'error' = 'success'
  ) => {
    console.log(`[${type.toUpperCase()}] ${message}`);
    // In a real app, this would show a toast notification
  };

  const startGaitAnalysis = useCallback(async (mode: AnalysisMode) => {
    const sessionId = `gait_${Date.now()}`;
    const newSession: GaitAnalysisSession = {
      id: sessionId,
      type: mode,
      startTime: new Date(),
      status: 'recording',
      insights: [],
      recommendations: [],
      riskScore: 0,
    };

    setActiveSession(newSession);
    setIsRecording(true);
    setAnalysisMode(mode);

    showToast(`Starting ${mode} gait analysis...`);
  }, []);

  const stopGaitAnalysis = useCallback(async () => {
    if (activeSession && isRecording) {
      const completedSession: GaitAnalysisSession = {
        ...activeSession,
        endTime: new Date(),
        status: 'analyzing',
      };

      setActiveSession(completedSession);
      setIsRecording(false);

      // Simulate analysis processing
      setTimeout(() => {
        const finalSession: GaitAnalysisSession = {
          ...completedSession,
          status: 'completed',
          insights: generateInsights(completedSession.type),
          recommendations: generateRecommendations(completedSession.type),
          riskScore: Math.random() * 100,
        };

        setActiveSession(finalSession);
        setSessionHistory((prev) => [finalSession, ...prev]);

        if (autoSave) {
          saveSession(finalSession);
        }

        showToast('Gait analysis completed');
      }, 3000);
    }
  }, [activeSession, isRecording, autoSave]);

  const generateInsights = (type: string): string[] => {
    const baseInsights = [
      'Walking steadiness within normal range',
      'Consistent step rhythm detected',
      'Balanced left-right foot placement',
    ];

    switch (type) {
      case 'lidar':
        return [
          ...baseInsights,
          'High-precision spatial measurements captured',
          'Detailed kinematic chain analysis completed',
          'Environmental context factors recorded',
        ];
      case 'pattern':
        return [
          ...baseInsights,
          'Movement pattern classification performed',
          'Temporal gait parameters analyzed',
          'Walking pattern consistency evaluated',
        ];
      case 'combined':
        return [
          ...baseInsights,
          'Comprehensive multi-modal analysis completed',
          'Cross-validated measurements obtained',
          'Enhanced accuracy through sensor fusion',
        ];
      default:
        return baseInsights;
    }
  };

  const generateRecommendations = (type: string): readonly string[] => {
    const baseRecs = [
      'Maintain current activity level',
      'Continue regular walking routine',
      'Monitor for any pattern changes',
    ];

    switch (type) {
      case 'lidar':
        return [
          ...baseRecs,
          'Consider periodic LiDAR assessments',
          'Focus on spatial awareness exercises',
        ];
      case 'pattern':
        return [
          ...baseRecs,
          'Practice rhythm-based walking exercises',
          'Work on movement consistency',
        ];
      case 'combined':
        return [
          ...baseRecs,
          'Comprehensive gait training program recommended',
          'Regular multi-modal assessments beneficial',
        ];
      default:
        return baseRecs;
    }
  };

  const saveSession = async (session: GaitAnalysisSession) => {
    try {
      // Simulate saving to storage
      localStorage.setItem(
        `gait_session_${session.id}`,
        JSON.stringify(session)
      );
      showToast('Session data saved');
    } catch (error) {
      showToast('Failed to save session data', 'error');
      console.error('Save error:', error);
    }
  };

  const exportData = useCallback(async () => {
    try {
      const exportData = {
        sessions: sessionHistory,
        exportDate: new Date().toISOString(),
        metadata: {
          totalSessions: sessionHistory.length,
          analysisTypes: [...new Set(sessionHistory.map((s) => s.type))],
        },
      };

      const blob = new Blob([JSON.stringify(exportData, null, 2)], {
        type: 'application/json',
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `gait_analysis_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      showToast('Data exported successfully');
    } catch (error) {
      showToast('Failed to export data', 'error');
      console.error('Export error:', error);
    }
  }, [sessionHistory]);

  const getRiskColor = (score: number) => {
    if (score < 25) return 'text-green-600 bg-green-50 border-green-200';
    if (score < 50) return 'text-yellow-600 bg-yellow-50 border-yellow-200';
    if (score < 75) return 'text-orange-600 bg-orange-50 border-orange-200';
    return 'text-red-600 bg-red-50 border-red-200';
  };

  const getRiskLevel = (score: number) => {
    if (score < 25) return 'Low';
    if (score < 50) return 'Moderate';
    if (score < 75) return 'High';
    return 'Critical';
  };

  // Load saved sessions on component mount
  useEffect(() => {
    const loadSavedSessions = () => {
      try {
        const keys = Object.keys(localStorage).filter((key) =>
          key.startsWith('gait_session_')
        );
        const sessions = keys
          .map((key) => {
            const data = localStorage.getItem(key);
            return data ? JSON.parse(data) : null;
          })
          .filter(Boolean);

        setSessionHistory(
          sessions.sort(
            (a, b) =>
              new Date(b.startTime).getTime() - new Date(a.startTime).getTime()
          )
        );
      } catch (error) {
        console.error('Failed to load saved sessions:', error);
      }
    };

    loadSavedSessions();
  }, []);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="flex items-center gap-2 text-3xl font-bold text-foreground">
            <Activity className="text-primary h-8 w-8" />
            Advanced Gait Analysis
          </h1>
          <p className="text-muted-foreground">
            Comprehensive walking pattern analysis using LiDAR and AI-powered
            insights
          </p>
        </div>
        <div className="flex items-center gap-2">
          {activeSession && (
            <Badge
              variant="outline"
              className={
                activeSession.status === 'recording'
                  ? 'bg-blue-50 text-blue-700'
                  : activeSession.status === 'analyzing'
                    ? 'bg-yellow-50 text-yellow-700'
                    : activeSession.status === 'completed'
                      ? 'bg-green-50 text-green-700'
                      : 'bg-gray-50 text-gray-700'
              }
            >
              {activeSession.status === 'recording' && (
                <div className="mr-2 h-2 w-2 animate-pulse rounded-full bg-blue-500" />
              )}
              {activeSession.status}
            </Badge>
          )}
          <Button onClick={exportData} variant="outline" size="sm">
            Export Data
          </Button>
        </div>
      </div>

      {/* Quick Action Panel */}
      {!isRecording && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Play className="h-5 w-5" />
              Start Analysis Session
            </CardTitle>
            <CardDescription>
              Choose an analysis mode to begin gait assessment
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
              {enableLiDAR && (
                <Button
                  onClick={() => startGaitAnalysis('lidar')}
                  className="flex h-auto flex-col items-center gap-2 p-4"
                  variant="outline"
                >
                  <Target className="h-6 w-6" />
                  <div className="text-center">
                    <div className="font-semibold">LiDAR Analysis</div>
                    <div className="text-muted-foreground text-xs">
                      High-precision spatial measurements
                    </div>
                  </div>
                </Button>
              )}

              {enablePatternAnalysis && (
                <Button
                  onClick={() => startGaitAnalysis('pattern')}
                  className="flex h-auto flex-col items-center gap-2 p-4"
                  variant="outline"
                >
                  <Activity className="h-6 w-6" />
                  <div className="text-center">
                    <div className="font-semibold">Pattern Analysis</div>
                    <div className="text-muted-foreground text-xs">
                      Movement pattern recognition
                    </div>
                  </div>
                </Button>
              )}

              {enableLiDAR && enablePatternAnalysis && (
                <Button
                  onClick={() => startGaitAnalysis('combined')}
                  className="flex h-auto flex-col items-center gap-2 p-4"
                  variant="default"
                >
                  <Brain className="h-6 w-6" />
                  <div className="text-center">
                    <div className="font-semibold">Combined Analysis</div>
                    <div className="text-muted-foreground text-xs">
                      Multi-modal comprehensive assessment
                    </div>
                  </div>
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Active Session Control */}
      {isRecording && activeSession && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Timer className="h-5 w-5 text-blue-500" />
              Recording{' '}
              {activeSession.type.charAt(0).toUpperCase() +
                activeSession.type.slice(1)}{' '}
              Analysis
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="text-muted-foreground text-sm">
                  Started: {activeSession.startTime.toLocaleTimeString()}
                </div>
                <Badge variant="secondary">{activeSession.type}</Badge>
              </div>
              <Button onClick={stopGaitAnalysis} variant="destructive">
                Stop Analysis
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Main Dashboard */}
      <Tabs
        value={dashboardView}
        onValueChange={(value: string) =>
          setDashboardView(value as DashboardView)
        }
        className="space-y-4"
      >
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="analysis">Live Analysis</TabsTrigger>
          <TabsTrigger value="insights">AI Insights</TabsTrigger>
          <TabsTrigger value="history">Session History</TabsTrigger>
          <TabsTrigger value="settings">Settings</TabsTrigger>
        </TabsList>

        <TabsContent value="analysis" className="space-y-4">
          {analysisMode === 'lidar' || analysisMode === 'combined' ? (
            <LiDARGaitAnalyzer
              onSessionComplete={(session) => {
                console.log('LiDAR session completed:', session);
              }}
            />
          ) : null}

          {analysisMode === 'pattern' || analysisMode === 'combined' ? (
            <WalkingPatternVisualizer
              isLiveMode={isRecording}
              onPatternDetected={(pattern) => {
                console.log('Pattern detected:', pattern);
              }}
            />
          ) : null}

          {!isRecording && !activeSession && (
            <Card>
              <CardContent className="py-12 text-center">
                <Activity className="mx-auto mb-4 h-12 w-12 text-gray-400" />
                <h3 className="mb-2 text-lg font-semibold">
                  No Active Analysis
                </h3>
                <p className="text-muted-foreground">
                  Start an analysis session to begin gait assessment
                </p>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="insights" className="space-y-4">
          {activeSession && activeSession.status === 'completed' ? (
            <>
              {/* Risk Assessment */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Heart className="h-5 w-5" />
                    Overall Risk Assessment
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4 text-center">
                    <div
                      className={`inline-flex items-center rounded-lg border px-4 py-3 ${getRiskColor(activeSession.riskScore)}`}
                    >
                      <span className="mr-3 text-3xl font-bold">
                        {Math.round(activeSession.riskScore)}
                      </span>
                      <div>
                        <div className="font-semibold">
                          {getRiskLevel(activeSession.riskScore)} Risk
                        </div>
                        <div className="text-sm opacity-90">
                          Fall Risk Score
                        </div>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* AI Insights */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Eye className="h-5 w-5" />
                    AI-Generated Insights
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {activeSession.insights.map((insight, index) => (
                      <div
                        key={`insight-${index}`}
                        className="flex items-start gap-2"
                      >
                        <CheckCircle className="mt-0.5 h-4 w-4 flex-shrink-0 text-green-500" />
                        <span className="text-sm">{insight}</span>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Recommendations */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Target className="h-5 w-5" />
                    Personalized Recommendations
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {activeSession.recommendations.map((rec, index) => (
                      <div
                        key={`rec-${index}`}
                        className="flex items-start gap-2"
                      >
                        <Target className="mt-0.5 h-4 w-4 flex-shrink-0 text-blue-500" />
                        <span className="text-sm">{rec}</span>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </>
          ) : (
            <Card>
              <CardContent className="py-12 text-center">
                <Brain className="mx-auto mb-4 h-12 w-12 text-gray-400" />
                <h3 className="mb-2 text-lg font-semibold">
                  No Insights Available
                </h3>
                <p className="text-muted-foreground">
                  Complete a gait analysis session to view AI-generated insights
                </p>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="history" className="space-y-4">
          {sessionHistory.length > 0 ? (
            <div className="space-y-4">
              {sessionHistory.map((session) => (
                <Card key={session.id}>
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <CardTitle className="flex items-center gap-2">
                        {session.type === 'lidar' && (
                          <Target className="h-5 w-5" />
                        )}
                        {session.type === 'pattern' && (
                          <Activity className="h-5 w-5" />
                        )}
                        {session.type === 'combined' && (
                          <Brain className="h-5 w-5" />
                        )}
                        {session.type.charAt(0).toUpperCase() +
                          session.type.slice(1)}{' '}
                        Analysis
                      </CardTitle>
                      <div className="flex items-center gap-2">
                        <Badge variant="outline">
                          {session.startTime.toLocaleDateString()}
                        </Badge>
                        <Badge className={getRiskColor(session.riskScore)}>
                          {getRiskLevel(session.riskScore)} Risk
                        </Badge>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <div className="text-muted-foreground text-sm">
                          Duration
                        </div>
                        <div className="font-semibold">
                          {session.endTime
                            ? Math.round(
                                (new Date(session.endTime).getTime() -
                                  new Date(session.startTime).getTime()) /
                                  1000
                              ) + 's'
                            : 'In Progress'}
                        </div>
                      </div>
                      <div>
                        <div className="text-muted-foreground text-sm">
                          Risk Score
                        </div>
                        <div className="font-semibold">
                          {Math.round(session.riskScore)}/100
                        </div>
                      </div>
                    </div>
                    {session.insights.length > 0 && (
                      <div className="mt-4">
                        <div className="text-muted-foreground mb-2 text-sm">
                          Key Insight
                        </div>
                        <div className="text-sm">{session.insights[0]}</div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            <Card>
              <CardContent className="py-12 text-center">
                <Clock className="mx-auto mb-4 h-12 w-12 text-gray-400" />
                <h3 className="mb-2 text-lg font-semibold">
                  No Session History
                </h3>
                <p className="text-muted-foreground">
                  Completed analysis sessions will appear here
                </p>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="settings" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Target className="h-5 w-5" />
                Analysis Settings
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <h4 className="font-medium">Available Analysis Types</h4>
                <div className="space-y-2">
                  <label className="flex items-center space-x-2">
                    <input type="checkbox" checked={enableLiDAR} readOnly />
                    <span className="text-sm">LiDAR Analysis</span>
                  </label>
                  <label className="flex items-center space-x-2">
                    <input
                      type="checkbox"
                      checked={enablePatternAnalysis}
                      readOnly
                    />
                    <span className="text-sm">Pattern Analysis</span>
                  </label>
                  <label className="flex items-center space-x-2">
                    <input type="checkbox" checked={autoSave} readOnly />
                    <span className="text-sm">Auto-save Sessions</span>
                  </label>
                </div>
              </div>

              <div className="space-y-2">
                <h4 className="font-medium">Data Management</h4>
                <div className="flex gap-2">
                  <Button variant="outline" size="sm" onClick={exportData}>
                    Export All Data
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      const keys = Object.keys(localStorage).filter((key) =>
                        key.startsWith('gait_session_')
                      );
                      keys.forEach((key) => localStorage.removeItem(key));
                      setSessionHistory([]);
                      showToast('All session data cleared');
                    }}
                  >
                    Clear All Sessions
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>System Information</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <div className="text-muted-foreground">Total Sessions</div>
                  <div className="font-semibold">{sessionHistory.length}</div>
                </div>
                <div>
                  <div className="text-muted-foreground">LiDAR Available</div>
                  <div className="font-semibold">
                    {enableLiDAR ? 'Yes' : 'No'}
                  </div>
                </div>
                <div>
                  <div className="text-muted-foreground">Pattern Analysis</div>
                  <div className="font-semibold">
                    {enablePatternAnalysis ? 'Enabled' : 'Disabled'}
                  </div>
                </div>
                <div>
                  <div className="text-muted-foreground">Auto-save</div>
                  <div className="font-semibold">{autoSave ? 'On' : 'Off'}</div>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { Alert, AlertDescription } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useWebSocket } from '@/hooks/useWebSocket';
import { useKV } from '@github/spark/hooks';
import {
  Activity,
  AlertTriangle,
  CheckCircle,
  Globe,
  Heart,
  Monitor,
  Radio,
  RefreshCw,
  Signal,
  Wifi,
  WifiOff,
  Zap,
} from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';

interface LiveMetric {
  id: string;
  type: 'heart_rate' | 'steps' | 'walking_steadiness' | 'activity' | 'sleep';
  value: number;
  unit: string;
  timestamp: string;
  deviceId: string;
  quality: 'excellent' | 'good' | 'fair' | 'poor';
}

interface ConnectionMetrics {
  totalMessages: number;
  messagesPerSecond: number;
  bytesTransferred: number;
  uptime: number;
  lastHeartbeat: string | null;
  reconnections: number;
  avgLatency: number;
}

export default function LiveConnectionDashboard() {
  const [isEnabled, setIsEnabled] = useKV<boolean>(
    'live-connection-enabled',
    false
  );
  const [liveMetrics, setLiveMetrics] = useState<LiveMetric[]>([]);
  const [connectionMetrics, setConnectionMetrics] = useState<ConnectionMetrics>(
    {
      totalMessages: 0,
      messagesPerSecond: 0,
      bytesTransferred: 0,
      uptime: 0,
      lastHeartbeat: null,
      reconnections: 0,
      avgLatency: 0,
    }
  );

  // Get WebSocket URL from window globals or use default
  const getWebSocketUrl = () => {
    if (typeof window !== 'undefined') {
      const customUrl = (window as any).__WS_URL__;
      if (customUrl) return customUrl;
    }
    return 'ws://localhost:3001';
  };

  // WebSocket message handlers
  const messageHandlers = {
    connection_established: (data: any) => {
      console.log('Connected to VitalSense WebSocket:', data);
      setConnectionMetrics((prev) => ({
        ...prev,
        lastHeartbeat: new Date().toISOString(),
      }));
    },

    live_health_update: (data: any) => {
      console.log('Live health update received:', data);
      if (data.metrics && Array.isArray(data.metrics)) {
        const newMetrics = data.metrics.map((metric: any) => ({
          id: `${metric.type}-${Date.now()}-${Math.random()}`,
          type: metric.type,
          value: metric.value,
          unit: metric.unit || '',
          timestamp: metric.timestamp || new Date().toISOString(),
          deviceId: data.deviceId || 'unknown',
          quality: determineDataQuality(metric.value, metric.type),
        }));

        setLiveMetrics((prev) => [...newMetrics, ...prev.slice(0, 99)]); // Keep last 100

        setConnectionMetrics((prev) => ({
          ...prev,
          totalMessages: prev.totalMessages + newMetrics.length,
          bytesTransferred: prev.bytesTransferred + JSON.stringify(data).length,
          lastHeartbeat: new Date().toISOString(),
        }));
      }
    },

    historical_data_update: (data: any) => {
      console.log('Historical data update:', data);
      // Handle historical data updates if needed
    },

    emergency_alert: (data: any) => {
      console.log('Emergency alert:', data);
      // Handle emergency alerts
    },

    error: (data: any) => {
      console.error('WebSocket error:', data);
    },

    pong: () => {
      setConnectionMetrics((prev) => ({
        ...prev,
        lastHeartbeat: new Date().toISOString(),
      }));
    },
  };

  // Initialize WebSocket connection
  const { connectionState, sendMessage, connect, disconnect } = useWebSocket(
    {
      url: getWebSocketUrl(),
      enableInDevelopment: true,
      reconnectAttempts: 10,
      reconnectDelay: 1000,
      pingInterval: 30000,
      onConnect: () => {
        console.log('Live connection established');
        // Send client identification
        sendMessage({
          type: 'client_identification',
          data: {
            clientType: 'web_dashboard',
            userId: 'demo-user',
            version: '1.0.0',
          },
          timestamp: new Date().toISOString(),
        });
      },
      onDisconnect: () => {
        console.log('Live connection lost');
        setConnectionMetrics((prev) => ({
          ...prev,
          reconnections: prev.reconnections + 1,
        }));
      },
      onError: (error) => {
        console.error('WebSocket error:', error);
      },
    },
    messageHandlers
  );

  // Determine data quality based on metric type and value
  const determineDataQuality = (
    value: number,
    type: string
  ): LiveMetric['quality'] => {
    switch (type) {
      case 'heart_rate':
        if (value >= 60 && value <= 100) return 'excellent';
        if (value >= 50 && value <= 120) return 'good';
        if (value >= 40 && value <= 140) return 'fair';
        return 'poor';
      case 'walking_steadiness':
        if (value >= 80) return 'excellent';
        if (value >= 60) return 'good';
        if (value >= 40) return 'fair';
        return 'poor';
      default:
        return 'good';
    }
  };

  // Toggle live connection
  const toggleConnection = useCallback(async () => {
    if (isEnabled) {
      disconnect();
      setIsEnabled(false);
      setLiveMetrics([]);
      setConnectionMetrics({
        totalMessages: 0,
        messagesPerSecond: 0,
        bytesTransferred: 0,
        uptime: 0,
        lastHeartbeat: null,
        reconnections: 0,
        avgLatency: 0,
      });
    } else {
      setIsEnabled(true);
      connect();
    }
  }, [isEnabled, connect, disconnect, setIsEnabled]);

  // Calculate messages per second
  useEffect(() => {
    if (!connectionState.isConnected) return;

    const interval = setInterval(() => {
      const now = Date.now();
      const oneSecondAgo = now - 1000;
      const recentMetrics = liveMetrics.filter(
        (metric) => new Date(metric.timestamp).getTime() > oneSecondAgo
      );

      setConnectionMetrics((prev) => ({
        ...prev,
        messagesPerSecond: recentMetrics.length,
        uptime: prev.uptime + 1,
      }));
    }, 1000);

    return () => clearInterval(interval);
  }, [connectionState.isConnected, liveMetrics]);

  // Get connection status icon
  const getConnectionIcon = () => {
    if (connectionState.isConnecting) {
      return <RefreshCw className="h-5 w-5 animate-spin text-yellow-500" />;
    }
    if (connectionState.isConnected) {
      return <Wifi className="h-5 w-5 text-green-500" />;
    }
    return <WifiOff className="h-5 w-5 text-red-500" />;
  };

  // Get metric icon
  const getMetricIcon = (type: string) => {
    switch (type) {
      case 'heart_rate':
        return <Heart className="h-4 w-4 text-red-500" />;
      case 'steps':
        return <Activity className="h-4 w-4 text-blue-500" />;
      case 'walking_steadiness':
        return <Radio className="h-4 w-4 text-green-500" />;
      case 'activity':
        return <Zap className="h-4 w-4 text-yellow-500" />;
      default:
        return <Monitor className="h-4 w-4 text-gray-500" />;
    }
  };

  // Get quality color
  const getQualityColor = (quality: string) => {
    switch (quality) {
      case 'excellent':
        return 'text-green-600';
      case 'good':
        return 'text-blue-600';
      case 'fair':
        return 'text-yellow-600';
      case 'poor':
        return 'text-red-600';
      default:
        return 'text-gray-600';
    }
  };

  // Format bytes
  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  // Format uptime
  const formatUptime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="flex items-center gap-2 text-2xl font-bold text-foreground">
            <Globe className="h-6 w-6" />
            Live Connection Dashboard
          </h2>
          <p className="text-muted-foreground">
            Real-time WebSocket connection to VitalSense health data streams
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium">Live Connection</span>
            <Switch checked={isEnabled} onCheckedChange={toggleConnection} />
          </div>
          {getConnectionIcon()}
        </div>
      </div>

      {/* Connection Status Alert */}
      {isEnabled && connectionState.error && (
        <Alert className="border-red-200 bg-red-50">
          <AlertTriangle className="h-4 w-4" />
          <AlertDescription>
            Connection error: {connectionState.error}
            {connectionState.reconnectAttempts > 0 && (
              <span className="ml-2">
                (Reconnect attempt {connectionState.reconnectAttempts})
              </span>
            )}
          </AlertDescription>
        </Alert>
      )}

      {isEnabled && connectionState.isConnecting && (
        <Alert className="border-yellow-200 bg-yellow-50">
          <RefreshCw className="h-4 w-4 animate-spin" />
          <AlertDescription>
            Connecting to VitalSense WebSocket server...
          </AlertDescription>
        </Alert>
      )}

      {isEnabled && connectionState.isConnected && (
        <Alert className="border-green-200 bg-green-50">
          <CheckCircle className="h-4 w-4" />
          <AlertDescription>
            Connected to VitalSense WebSocket server. Receiving live health
            data.
          </AlertDescription>
        </Alert>
      )}

      {/* Main Stats */}
      <div className="grid grid-cols-1 gap-4 md:grid-cols-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm font-medium">
                  Connection Status
                </p>
                <div className="mt-1 flex items-center gap-2">
                  {getConnectionIcon()}
                  <span className="font-semibold">
                    {connectionState.isConnected
                      ? 'Connected'
                      : connectionState.isConnecting
                        ? 'Connecting'
                        : 'Disconnected'}
                  </span>
                </div>
              </div>
              <Signal className="text-muted-foreground h-8 w-8" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm font-medium">
                  Message Rate
                </p>
                <p className="text-2xl font-bold">
                  {connectionMetrics.messagesPerSecond}
                </p>
                <p className="text-muted-foreground text-xs">per second</p>
              </div>
              <Activity className="text-muted-foreground h-8 w-8" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm font-medium">
                  Total Messages
                </p>
                <p className="text-2xl font-bold">
                  {connectionMetrics.totalMessages}
                </p>
                <p className="text-muted-foreground text-xs">this session</p>
              </div>
              <Monitor className="text-muted-foreground h-8 w-8" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm font-medium">
                  Uptime
                </p>
                <p className="text-2xl font-bold">
                  {formatUptime(connectionMetrics.uptime)}
                </p>
                <p className="text-muted-foreground text-xs">
                  {connectionMetrics.reconnections > 0 &&
                    `${connectionMetrics.reconnections} reconnects`}
                </p>
              </div>
              <Zap className="text-muted-foreground h-8 w-8" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Main Interface */}
      <Tabs defaultValue="live-stream" className="space-y-6">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="live-stream">Live Stream</TabsTrigger>
          <TabsTrigger value="metrics">Metrics</TabsTrigger>
          <TabsTrigger value="technical">Technical</TabsTrigger>
        </TabsList>

        <TabsContent value="live-stream" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Activity className="h-5 w-5" />
                Live Health Metrics Stream
              </CardTitle>
              <CardDescription>
                Real-time health data as it arrives from connected devices
              </CardDescription>
            </CardHeader>
            <CardContent>
              {liveMetrics.length === 0 ? (
                <div className="text-muted-foreground py-8 text-center">
                  {isEnabled && connectionState.isConnected ? (
                    <>
                      <Monitor className="mx-auto mb-4 h-12 w-12 opacity-50" />
                      <p>Waiting for live health data...</p>
                      <p className="text-sm">
                        Make sure your devices are connected and sending data.
                      </p>
                    </>
                  ) : (
                    <>
                      <WifiOff className="mx-auto mb-4 h-12 w-12 opacity-50" />
                      <p>Live connection is disabled</p>
                      <p className="text-sm">
                        Enable the live connection to see real-time health data.
                      </p>
                    </>
                  )}
                </div>
              ) : (
                <div className="max-h-96 space-y-2 overflow-y-auto">
                  {liveMetrics.slice(0, 20).map((metric) => (
                    <div
                      key={metric.id}
                      className="bg-muted/50 flex items-center justify-between rounded-lg p-3"
                    >
                      <div className="flex items-center gap-3">
                        {getMetricIcon(metric.type)}
                        <div>
                          <p className="font-medium capitalize">
                            {metric.type.replace('_', ' ')}
                          </p>
                          <p className="text-muted-foreground text-sm">
                            {metric.deviceId}
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-bold">
                          {metric.value} {metric.unit}
                        </p>
                        <div className="flex items-center gap-2">
                          <Badge
                            variant="outline"
                            className={getQualityColor(metric.quality)}
                          >
                            {metric.quality}
                          </Badge>
                          <span className="text-muted-foreground text-xs">
                            {new Date(metric.timestamp).toLocaleTimeString()}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="metrics" className="space-y-6">
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle>Connection Performance</CardTitle>
                <CardDescription>
                  Real-time connection metrics and performance stats
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex justify-between">
                  <span>Data Transferred</span>
                  <span className="font-mono">
                    {formatBytes(connectionMetrics.bytesTransferred)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>Average Latency</span>
                  <span className="font-mono">
                    {connectionMetrics.avgLatency}ms
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>Reconnections</span>
                  <span className="font-mono">
                    {connectionMetrics.reconnections}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>Last Heartbeat</span>
                  <span className="font-mono text-sm">
                    {connectionMetrics.lastHeartbeat
                      ? new Date(
                          connectionMetrics.lastHeartbeat
                        ).toLocaleTimeString()
                      : 'Never'}
                  </span>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Data Quality</CardTitle>
                <CardDescription>
                  Analysis of incoming health data quality
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {['excellent', 'good', 'fair', 'poor'].map((quality) => {
                  const count = liveMetrics.filter(
                    (m) => m.quality === quality
                  ).length;
                  const percentage =
                    liveMetrics.length > 0
                      ? (count / liveMetrics.length) * 100
                      : 0;

                  return (
                    <div key={quality} className="space-y-2">
                      <div className="flex justify-between">
                        <span
                          className={`capitalize ${getQualityColor(quality)}`}
                        >
                          {quality}
                        </span>
                        <span>
                          {count} ({percentage.toFixed(1)}%)
                        </span>
                      </div>
                      <Progress value={percentage} className="h-2" />
                    </div>
                  );
                })}
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="technical" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Technical Details</CardTitle>
              <CardDescription>
                WebSocket connection configuration and debugging information
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium">WebSocket URL</label>
                  <p className="bg-muted rounded p-2 font-mono text-sm">
                    {getWebSocketUrl()}
                  </p>
                </div>
                <div>
                  <label className="text-sm font-medium">Ready State</label>
                  <p className="bg-muted rounded p-2 font-mono text-sm">
                    {connectionState.isConnected
                      ? 'OPEN (1)'
                      : connectionState.isConnecting
                        ? 'CONNECTING (0)'
                        : 'CLOSED (3)'}
                  </p>
                </div>
              </div>

              <div className="space-y-2">
                <Button
                  onClick={() => {
                    sendMessage({
                      type: 'ping',
                      data: { timestamp: Date.now() },
                      timestamp: new Date().toISOString(),
                    });
                  }}
                  disabled={!connectionState.isConnected}
                  variant="outline"
                  size="sm"
                >
                  Send Ping
                </Button>

                <Button
                  onClick={() => {
                    sendMessage({
                      type: 'subscribe_health_updates',
                      data: {
                        metrics: ['heart_rate', 'steps', 'walking_steadiness'],
                        userId: 'demo-user',
                      },
                      timestamp: new Date().toISOString(),
                    });
                  }}
                  disabled={!connectionState.isConnected}
                  variant="outline"
                  size="sm"
                >
                  Subscribe to Health Updates
                </Button>
              </div>

              {connectionState.error && (
                <Alert className="border-red-200 bg-red-50">
                  <AlertTriangle className="h-4 w-4" />
                  <AlertDescription>
                    <strong>Error:</strong> {connectionState.error}
                  </AlertDescription>
                </Alert>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

