/**
 * Enhanced Authentication Context with HIPAA Compliance
 *
 * Features:
 * - Secure user session management
 * - Role-based access control
 * - Automatic token refresh
 * - Audit logging for health data access
 * - MFA enforcement
 * - Session timeout protection
 */

import {
  auth0Config,
  getAuth0ConfigForEnvironment,
  USER_ROLES,
  type Permission,
  type UserRole,
} from '@/lib/auth0Config';
import { Auth0Provider, useAuth0 } from '@auth0/auth0-react';
import {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from 'react';
import { toast } from 'sonner';

interface UserProfile {
  id: string;
  email: string;
  name: string;
  picture?: string;
  roles: UserRole[];
  permissions: Permission[];
  lastLogin: string;
  mfaEnabled: boolean;
  hipaaConsent: boolean;
  emergencyContacts?: string[];
}

interface AuthContextType {
  // User state
  user: UserProfile | null;
  isAuthenticated: boolean;
  isLoading: boolean;

  // Authentication methods
  login: () => Promise<void>;
  logout: () => Promise<void>;

  // Permission checking
  hasRole: (role: UserRole) => boolean;
  hasPermission: (permission: Permission) => boolean;
  hasAnyPermission: (permissions: Permission[]) => boolean;

  // Session management
  refreshSession: () => Promise<void>;
  validateSession: () => Promise<boolean>;

  // Security methods
  getAccessToken: () => Promise<string | undefined>;
  getIdToken: () => Promise<string | undefined>;

  // Audit logging
  logHealthDataAccess: (action: string, resource: string) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Lightweight logger shim
const authLog = {
  info: (...args: unknown[]) => {
    try {
      console.info('[auth]', ...args);
    } catch {
      /* no-op */
    }
  },
  warn: (...args: unknown[]) => {
    try {
      console.warn('[auth]', ...args);
    } catch {
      /* no-op */
    }
  },
  error: (...args: unknown[]) => {
    try {
      console.error('[auth]', ...args);
    } catch {
      /* no-op */
    }
  },
};

export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

interface AuthProviderProps {
  children: ReactNode;
}

function AuthContextProvider({ children }: AuthProviderProps) {
  const {
    user: auth0User,
    isAuthenticated: auth0IsAuthenticated,
    isLoading: auth0IsLoading,
    loginWithRedirect,
    logout: auth0Logout,
    getAccessTokenSilently,
    getIdTokenClaims,
  } = useAuth0();

  const [user, setUser] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const hipaaWarnedRef = useRef(false);
  const sessionGet = (k: string): string | null => {
    try {
      return typeof window !== 'undefined'
        ? window.sessionStorage.getItem(k)
        : null;
    } catch {
      return null;
    }
  };
  const sessionSet = (k: string, v: string) => {
    try {
      if (typeof window !== 'undefined') window.sessionStorage.setItem(k, v);
    } catch {
      /* no-op */
    }
  };

  // Extract user profile from Auth0 user
  const buildUserProfile =
    useCallback(async (): Promise<UserProfile | null> => {
      if (!auth0User || !auth0IsAuthenticated) return null;

      try {
        // Get access token to extract permissions and roles
        await getAccessTokenSilently();
        const idToken = await getIdTokenClaims();

        // Extract roles and permissions from token claims
        const roles = (idToken?.[
          'https://vitalsense.app/roles'
        ] as UserRole[]) || [USER_ROLES.PATIENT];
        const permissions =
          (idToken?.['https://vitalsense.app/permissions'] as Permission[]) ||
          [];

        // Check for required HIPAA consent
        const hipaaConsent =
          idToken?.['https://vitalsense.app/hipaa_consent'] === true;
        const mfaEnabled =
          idToken?.['https://vitalsense.app/mfa_enabled'] === true;

        const profile: UserProfile = {
          id: auth0User.sub || '',
          email: auth0User.email || '',
          name: auth0User.name || '',
          picture: auth0User.picture,
          roles,
          permissions,
          lastLogin: new Date().toISOString(),
          mfaEnabled,
          hipaaConsent,
          emergencyContacts: idToken?.[
            'https://vitalsense.app/emergency_contacts'
          ] as string[],
        };

        // Log successful authentication
        authLog.info('user_authentication', {
          userId: profile.id,
          email: profile.email,
          roles,
          mfaEnabled,
          hipaaConsent,
        });

        return profile;
      } catch (error) {
        authLog.error('build_user_profile_error', error, {
          operation: 'build_user_profile',
          userId: auth0User.sub,
        });
        return null;
      }
    }, [
      auth0User,
      auth0IsAuthenticated,
      getAccessTokenSilently,
      getIdTokenClaims,
    ]);

  // Update user profile when Auth0 state changes
  useEffect(() => {
    const updateUserProfile = async () => {
      setIsLoading(true);
      const profile = await buildUserProfile();
      setUser(profile);
      setIsLoading(false);

      // HIPAA consent: no toast here; inline banner handles user messaging
      if (profile && !profile.hipaaConsent) {
        const key = `hipaa:warned:${profile.id}`;
        const already = hipaaWarnedRef.current || !!sessionGet(key);
        if (!already) {
          hipaaWarnedRef.current = true;
          sessionSet(key, '1');
        }
      }

      // Enforce MFA for healthcare providers and admins
      if (
        profile &&
        (profile.roles.includes(USER_ROLES.HEALTHCARE_PROVIDER) ||
          profile.roles.includes(USER_ROLES.ADMIN)) &&
        !profile.mfaEnabled
      ) {
        toast.error('Multi-factor authentication is required for your role');
        // Could redirect to MFA setup
      }
    };

    if (auth0IsAuthenticated && auth0User) {
      updateUserProfile();
    } else {
      setUser(null);
      setIsLoading(auth0IsLoading);
    }
  }, [auth0IsAuthenticated, auth0User, auth0IsLoading, buildUserProfile]);

  // Authentication methods
  const login = useCallback(async () => {
    try {
      await loginWithRedirect({
        authorizationParams: {
          audience: auth0Config.audience,
          scope: auth0Config.scope,
        },
      });
    } catch (error) {
      authLog.error('login_failed', error);
      toast.error('Login failed. Please try again.');
    }
  }, [loginWithRedirect]);

  const logout = useCallback(async () => {
    try {
      // Log logout event
      if (user) {
        authLog.info('user_logout', {
          userId: user.id,
          email: user.email,
        });
      }

      await auth0Logout({
        logoutParams: {
          returnTo: auth0Config.logoutUri,
        },
      });
    } catch (error) {
      authLog.error('logout_failed', error);
      toast.error('Logout failed. Please clear your browser cache.');
    }
  }, [auth0Logout, user]);

  // Permission checking methods
  const hasRole = useCallback(
    (role: UserRole): boolean => {
      return user?.roles.includes(role) || false;
    },
    [user]
  );

  const hasPermission = useCallback(
    (permission: Permission): boolean => {
      return user?.permissions.includes(permission) || false;
    },
    [user]
  );

  const hasAnyPermission = useCallback(
    (permissions: Permission[]): boolean => {
      return permissions.some((permission) => hasPermission(permission));
    },
    [hasPermission]
  );

  // Session management
  const refreshSession = useCallback(async () => {
    try {
      await getAccessTokenSilently({ cacheMode: 'off' });
      const profile = await buildUserProfile();
      setUser(profile);
    } catch (error) {
      authLog.error('refresh_session_failed', error);
      throw error;
    }
  }, [getAccessTokenSilently, buildUserProfile]);

  const validateSession = useCallback(async (): Promise<boolean> => {
    try {
      const token = await getAccessTokenSilently();
      return !!token;
    } catch (error) {
      authLog.error('validate_session_failed', error);
      return false;
    }
  }, [getAccessTokenSilently]);

  // Token methods
  const getAccessToken = useCallback(async (): Promise<string | undefined> => {
    try {
      return await getAccessTokenSilently();
    } catch (error) {
      authLog.error('get_access_token_failed', error);
      return undefined;
    }
  }, [getAccessTokenSilently]);

  const getIdToken = useCallback(async (): Promise<string | undefined> => {
    try {
      const claims = await getIdTokenClaims();
      return claims?.__raw;
    } catch (error) {
      authLog.error('get_id_token_failed', error);
      return undefined;
    }
  }, [getIdTokenClaims]);

  // Audit logging for health data access
  const logHealthDataAccess = useCallback(
    (action: string, resource: string) => {
      if (user) {
        authLog.info('health_data_access', {
          userId: user.id,
          action,
          resource,
          timestamp: new Date().toISOString(),
        });
      }
    },
    [user]
  );

  const contextValue: AuthContextType = {
    user,
    isAuthenticated: auth0IsAuthenticated && !!user,
    isLoading,
    login,
    logout,
    hasRole,
    hasPermission,
    hasAnyPermission,
    refreshSession,
    validateSession,
    getAccessToken,
    getIdToken,
    logHealthDataAccess,
  };

  return (
    <AuthContext.Provider value={contextValue}>{children}</AuthContext.Provider>
  );
}

// Main Auth Provider component
export function AuthProvider({ children }: AuthProviderProps) {
  const config = getAuth0ConfigForEnvironment();

  return (
    <Auth0Provider
      domain={config.domain}
      clientId={config.clientId}
      authorizationParams={{
        redirect_uri: config.redirectUri,
        audience: config.audience,
        scope: config.scope,
      }}
      useRefreshTokens={config.useRefreshTokens}
      cacheLocation={config.cacheLocation}
    >
      <AuthContextProvider>{children}</AuthContextProvider>
    </Auth0Provider>
  );
}

import { describe, expect, it } from 'vitest';
import { severityNumeric } from '../gaitMomentum';
import { classifySeverity, computeSingleMetricTrend } from '../gaitTrends';

function classify(values: number[]) {
  return classifySeverity(computeSingleMetricTrend(values));
}

describe('gait severity boundaries', () => {
  it('insufficient_data when relative slope tiny (low confidence)', () => {
    const tr = classify([1, 1.0005, 1.0008]);
    expect(tr.severity).toBe('insufficient_data');
  });
  it('increasing pattern shows non-decreasing severity ordering', () => {
    const mildish = classify([1, 1.004, 1.008, 1.011, 1.013]);
    const moderateish = classify([1, 1.012, 1.024, 1.036, 1.048]);
    const strongish = classify([1, 1.05, 1.09, 1.14, 1.2]);
    const s1 = severityNumeric(mildish.severity as any);
    const s2 = severityNumeric(moderateish.severity as any);
    const s3 = severityNumeric(strongish.severity as any);
    expect(s2).toBeGreaterThanOrEqual(s1);
    expect(s3).toBeGreaterThanOrEqual(s2);
  });
  it('declining pattern yields negative severity that grows in magnitude', () => {
    const mildDecline = classify([1.2, 1.195, 1.19, 1.185, 1.18]);
    const strongerDecline = classify([1.2, 1.18, 1.16, 1.14, 1.12]);
    const sd1 = severityNumeric(mildDecline.severity as any);
    const sd2 = severityNumeric(strongerDecline.severity as any);
    // Both should be <= 0 and sd2 should be <= sd1 (more negative)
    expect(sd1).toBeLessThanOrEqual(0);
    expect(sd2).toBeLessThanOrEqual(sd1);
  });
});

/**
 * Health Data Processing Utilities
 * Handles parsing, validation, and analysis of Apple Health data exports
 */

export interface HealthMetric {
  date: string;
  value: number;
  unit?: string;
}

/**
 * Aggregated analytics snapshot produced by HealthDataProcessor.
 * NOTE: This is intentionally distinct from the event-level `ProcessedHealthData`
 * defined in `@/schemas/health` (a single processed metric reading).
 * To reduce ambiguity elsewhere you may import this as `AnalyticsHealthData`.
 */
export interface ProcessedHealthData {
  lastUpdated: string;
  dataQuality: {
    completeness: number;
    consistency: number;
    recency: number;
    overall: 'excellent' | 'good' | 'fair' | 'poor';
  };
  metrics: {
    steps: MetricData;
    heartRate: MetricData;
    walkingSteadiness: MetricData;
    sleepHours: MetricData;
    bodyWeight?: MetricData;
    bloodPressure?: MetricData;
    activeEnergy?: MetricData;
    distanceWalking?: MetricData;
  };
  insights: string[];
  fallRiskFactors: FallRiskFactor[];
  healthScore: number;
}

export interface MetricData {
  daily: HealthMetric[];
  weekly: HealthMetric[];
  monthly: HealthMetric[];
  average: number;
  trend: 'increasing' | 'decreasing' | 'stable';
  variability: number;
  reliability: number;
  lastValue: number;
  percentileRank: number;
}

export interface FallRiskFactor {
  factor: string;
  risk: 'low' | 'moderate' | 'high';
  impact: number;
  recommendation: string;
}

// Preferred alias to disambiguate from schema-level single reading type
export type AnalyticsHealthData = ProcessedHealthData;

/**
 * Processes raw health data and returns structured analytics
 */
export class HealthDataProcessor {
  private static generateTimeSeriesData(
    days: number,
    baseValue: number,
    variance: number,
    trend: number = 0
  ): HealthMetric[] {
    return Array.from({ length: days }, (_, i) => {
      const trendComponent = trend * i;
      const randomComponent = (Math.random() - 0.5) * variance;
      const value = Math.max(0, baseValue + trendComponent + randomComponent);

      return {
        date: new Date(Date.now() - (days - 1 - i) * 24 * 60 * 60 * 1000)
          .toISOString()
          .split('T')[0],
        value: Math.round(value * 100) / 100,
      };
    });
  }

  private static calculateTrend(
    data: HealthMetric[]
  ): 'increasing' | 'decreasing' | 'stable' {
    if (data.length < 3) return 'stable';

    const recentValues = data.slice(-7).map((d) => d.value);
    const olderValues = data.slice(-14, -7).map((d) => d.value);

    const recentAvg =
      recentValues.reduce((a, b) => a + b, 0) / recentValues.length;
    const olderAvg =
      olderValues.reduce((a, b) => a + b, 0) / olderValues.length;

    const changePercent = ((recentAvg - olderAvg) / olderAvg) * 100;

    if (changePercent > 5) return 'increasing';
    if (changePercent < -5) return 'decreasing';
    return 'stable';
  }

  private static calculateVariability(data: HealthMetric[]): number {
    if (data.length < 2) return 0;

    const values = data.map((d) => d.value);
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const variance =
      values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;

    return (Math.sqrt(variance) / mean) * 100; // Coefficient of variation
  }

  private static aggregateToWeekly(daily: HealthMetric[]): HealthMetric[] {
    const weekly: HealthMetric[] = [];

    for (let i = 0; i < daily.length; i += 7) {
      const weekData = daily.slice(i, i + 7);
      if (weekData.length > 0) {
        const weekAvg =
          weekData.reduce((sum, day) => sum + day.value, 0) / weekData.length;
        weekly.push({
          date: weekData[weekData.length - 1].date, // End of week
          value: Math.round(weekAvg * 100) / 100,
        });
      }
    }

    return weekly;
  }

  private static processMetric(
    daily: HealthMetric[],
    metricName: string
  ): MetricData {
    const average = daily.reduce((sum, d) => sum + d.value, 0) / daily.length;
    const trend = this.calculateTrend(daily);
    const variability = this.calculateVariability(daily);
    const weekly = this.aggregateToWeekly(daily);
    const monthly = this.aggregateToWeekly(weekly);

    // Calculate reliability based on data consistency
    const reliability = Math.max(0, 100 - variability);

    // Calculate percentile rank (simplified)
    const sortedValues = daily.map((d) => d.value).sort((a, b) => a - b);
    const lastValue = daily[daily.length - 1]?.value || 0;
    const percentileRank =
      (sortedValues.filter((v) => v <= lastValue).length /
        sortedValues.length) *
      100;

    return {
      daily,
      weekly,
      monthly,
      average: Math.round(average * 100) / 100,
      trend,
      variability: Math.round(variability * 100) / 100,
      reliability: Math.round(reliability * 100) / 100,
      lastValue,
      percentileRank: Math.round(percentileRank),
    };
  }

  private static generateInsights(
    metrics: ProcessedHealthData['metrics']
  ): string[] {
    const insights: string[] = [];

    // Walking steadiness insights
    if (metrics.walkingSteadiness.average < 60) {
      insights.push(
        `Walking steadiness is below average (${Math.round(metrics.walkingSteadiness.average)}%). Consider balance exercises and consulting your healthcare provider.`
      );
    } else if (metrics.walkingSteadiness.trend === 'decreasing') {
      insights.push(
        `Walking steadiness has declined by ${Math.round(metrics.walkingSteadiness.variability)}% recently. Monitor for changes and consider preventive measures.`
      );
    }

    // Activity insights
    if (metrics.steps.average < 5000) {
      insights.push(
        `Daily step count is below recommended levels. Aim for gradual increases in physical activity.`
      );
    } else if (metrics.steps.trend === 'increasing') {
      insights.push(
        `Great progress! Your activity levels have increased by ${Math.round(((metrics.steps.lastValue - metrics.steps.average) / metrics.steps.average) * 100)}% recently.`
      );
    }

    // Heart rate insights
    if (metrics.heartRate.variability > 15) {
      insights.push(
        `Heart rate shows high variability. This could indicate stress or irregular patterns worth discussing with your doctor.`
      );
    }

    // Sleep insights
    if (metrics.sleepHours.average < 7) {
      insights.push(
        `Sleep duration is below recommended 7-9 hours. Poor sleep can affect balance and increase fall risk.`
      );
    }

    // Correlation insights
    if (
      metrics.steps.trend === 'increasing' &&
      metrics.sleepHours.trend === 'increasing'
    ) {
      insights.push(
        `Your increased activity appears to correlate with better sleep quality - an excellent positive cycle!`
      );
    }

    return insights;
  }

  private static calculateFallRiskFactors(
    metrics: ProcessedHealthData['metrics']
  ): FallRiskFactor[] {
    const factors: FallRiskFactor[] = [];

    // Walking steadiness factor
    if (metrics.walkingSteadiness.average < 50) {
      factors.push({
        factor: 'Walking Steadiness',
        risk: 'high',
        impact: 40,
        recommendation:
          'Consult with a physical therapist for balance training exercises',
      });
    } else if (metrics.walkingSteadiness.average < 70) {
      factors.push({
        factor: 'Walking Steadiness',
        risk: 'moderate',
        impact: 25,
        recommendation:
          'Practice daily balance exercises and consider tai chi classes',
      });
    }

    // Activity level factor
    if (metrics.steps.average < 3000) {
      factors.push({
        factor: 'Low Activity Level',
        risk: 'high',
        impact: 30,
        recommendation:
          'Gradually increase daily movement with safe, supervised activities',
      });
    } else if (metrics.steps.average < 5000) {
      factors.push({
        factor: 'Moderate Activity Level',
        risk: 'moderate',
        impact: 15,
        recommendation: 'Aim for 6,000-8,000 steps daily through regular walks',
      });
    }

    // Heart rate variability factor
    if (metrics.heartRate.variability > 20) {
      factors.push({
        factor: 'Heart Rate Irregularity',
        risk: 'moderate',
        impact: 20,
        recommendation:
          'Monitor cardiovascular health and consult with your physician',
      });
    }

    return factors;
  }

  private static calculateDataQuality(
    metrics: ProcessedHealthData['metrics']
  ): ProcessedHealthData['dataQuality'] {
    // Calculate completeness (how much data we have)
    const expectedDays = 30;
    const actualDays = Math.max(
      metrics.steps.daily.length,
      metrics.heartRate.daily.length,
      metrics.walkingSteadiness.daily.length
    );
    const completeness = (actualDays / expectedDays) * 100;

    // Calculate consistency (how reliable the data is)
    const avgReliability =
      [
        metrics.steps.reliability,
        metrics.heartRate.reliability,
        metrics.walkingSteadiness.reliability,
      ].reduce((a, b) => a + b, 0) / 3;

    // Calculate recency (how recent the data is)
    const lastDataDate = new Date(
      metrics.steps.daily[metrics.steps.daily.length - 1]?.date || 0
    );
    const daysSinceLastData = Math.floor(
      (Date.now() - lastDataDate.getTime()) / (1000 * 60 * 60 * 24)
    );
    const recency = Math.max(0, 100 - daysSinceLastData * 10);

    const overall = (completeness + avgReliability + recency) / 3;

    let overallRating: 'excellent' | 'good' | 'fair' | 'poor';
    if (overall >= 85) overallRating = 'excellent';
    else if (overall >= 70) overallRating = 'good';
    else if (overall >= 50) overallRating = 'fair';
    else overallRating = 'poor';

    return {
      completeness: Math.round(completeness),
      consistency: Math.round(avgReliability),
      recency: Math.round(recency),
      overall: overallRating,
    };
  }

  private static calculateHealthScore(
    metrics: ProcessedHealthData['metrics'],
    fallRiskFactors: FallRiskFactor[]
  ): number {
    let score = 100;

    // Deduct points for fall risk factors
    const totalRiskImpact = fallRiskFactors.reduce(
      (sum, factor) => sum + factor.impact,
      0
    );
    score -= totalRiskImpact;

    // Bonus points for good trends
    if (metrics.steps.trend === 'increasing') score += 5;
    if (metrics.walkingSteadiness.trend === 'increasing') score += 10;
    if (metrics.sleepHours.average >= 7) score += 5;

    return Math.max(0, Math.min(100, Math.round(score)));
  }

  /**
   * Main processing function that converts raw data into structured analytics
   */
  static async processHealthData(file?: File): Promise<ProcessedHealthData> {
    // For now, generate realistic mock data
    // In a real implementation, this would parse the actual Apple Health XML

    const steps = this.generateTimeSeriesData(90, 6500, 2000, -10);
    const heartRate = this.generateTimeSeriesData(90, 68, 8, 0.1);
    const walkingSteadiness = this.generateTimeSeriesData(90, 75, 15, -0.5);
    const sleepHours = this.generateTimeSeriesData(90, 7.2, 1.5, 0.02);
    const bodyWeight = this.generateTimeSeriesData(90, 70, 2, -0.01);
    const activeEnergy = this.generateTimeSeriesData(90, 450, 150, -2);

    const processedMetrics = {
      steps: this.processMetric(steps, 'steps'),
      heartRate: this.processMetric(heartRate, 'heartRate'),
      walkingSteadiness: this.processMetric(
        walkingSteadiness,
        'walkingSteadiness'
      ),
      sleepHours: this.processMetric(sleepHours, 'sleepHours'),
      bodyWeight: this.processMetric(bodyWeight, 'bodyWeight'),
      activeEnergy: this.processMetric(activeEnergy, 'activeEnergy'),
      distanceWalking: this.processMetric(
        steps.map((s) => ({ ...s, value: s.value * 0.0008 })), // Convert steps to km
        'distanceWalking'
      ),
    };

    const fallRiskFactors = this.calculateFallRiskFactors(processedMetrics);
    const insights = this.generateInsights(processedMetrics);
    const dataQuality = this.calculateDataQuality(processedMetrics);
    const healthScore = this.calculateHealthScore(
      processedMetrics,
      fallRiskFactors
    );

    return {
      lastUpdated: new Date().toISOString(),
      dataQuality,
      metrics: processedMetrics,
      insights,
      fallRiskFactors,
      healthScore,
    };
  }
}

