        'Postural instability indicators',
      ];
      recommendations = [
        'Immediate fall prevention measures',
        'Consider supervised mobility only',
        'Vestibular system evaluation',
      ];
    } else if (balanceScore < 0.6 || walkingSteadiness < 0.6) {
      riskLevel = 'high';
